export const canEditRelations = (manga?: Manga): boolean => {
	if (!Session.hasRole(Role.Sysop, Role.Staff, Role.Moderator) && (manga?.locked || !manga?.deleted_at)) {
		return false;
	}
	return Session.hasPerm("manga.relation.edit");
};

after:
export const canEditRelations = (manga?: Manga): boolean => {
	const actor = get(Session);
	if (!actor?.identity?.id) return false;
	// The create form has no saved title yet; its future draft owner needs manga.create.
	if (!manga) return Session.hasPerm("manga.create");
	const current = manga as Manga & { can_mutate?: boolean; is_unavailable?: boolean };
	if (manga.deleted_at || current.can_mutate === false || current.is_unavailable) return false;
	if (Session.hasRole(Role.Sysop, Role.Staff, Role.Moderator) && Session.hasPerm("manga.relation.edit")) return true;
	if (manga.locked) return false;
	if (manga.state === State.Published) return Session.hasPerm("manga.relation.edit");
	return manga.relationships?.submitter?.id === actor.identity.id && Session.hasPerm("manga.create");
};
